options.styles:
.ownership-dashboard {
  width: 100%;
  box-sizing: border-box;
  padding: 18px;
  background: #eef3f8;
  color: #102a43;
  font-family: "Segoe UI", Arial, sans-serif;
}

.ownership-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}

.ownership-title {
  color: #102a43;
  font-size: 23px;
  font-weight: 600;
  line-height: 1.2;
}

.ownership-subtitle {
  margin-top: 5px;
  color: #627d98;
  font-size: 13px;
}

.score-summary {
  min-width: 138px;
  box-sizing: border-box;
  padding: 10px 14px;
  border: 1px solid #d4deea;
  border-radius: 7px;
  background: #ffffff;
  box-shadow: 0 1px 3px rgba(16, 42, 67, 0.08);
  text-align: right;
}

.score-summary-label {
  display: block;
  color: #627d98;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.6px;
  text-transform: uppercase;
}

.score-summary-value {
  display: block;
  margin-top: 3px;
  color: #102a43;
  font-size: 20px;
  font-weight: 700;
}

.ownership-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(180px, 1fr));
  gap: 14px;
}

.ownership-card {
  position: relative;
  min-height: 128px;
  box-sizing: border-box;
  overflow: hidden;
  padding: 20px 17px 15px;
  border: 1px solid #d4deea;
  border-radius: 7px;
  background: #ffffff;
  box-shadow: 0 2px 5px rgba(16, 42, 67, 0.09);
}

.ownership-card::before {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 4px;
  content: "";
  background: #4c9aff;
}

.ownership-label {
  min-height: 28px;
  color: #486581;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.5px;
  line-height: 1.3;
  text-transform: uppercase;
}

.ownership-value {
  margin-top: 6px;
  color: #102a43;
  font-size: 35px;
  font-weight: 700;
  line-height: 1;
}

.ownership-description {
  margin-top: 9px;
  color: #829ab1;
  font-size: 11px;
  line-height: 1.35;
}

.score-suffix {
  margin-left: 3px;
  color: #829ab1;
  font-size: 15px;
  font-weight: 600;
}

.score-badge {
  display: inline-block;
  margin-top: 9px;
  padding: 4px 9px;
  border-radius: 12px;
  background: #ffedd5;
  color: #9a3412;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.35px;
  text-transform: uppercase;
}

.card-blue::before {
  background: #4c9aff;
}

.card-red::before {
  background: #e5484d;
}

.card-dark-red::before {
  background: #b42318;
}

.card-orange::before {
  background: #f47b20;
}

.card-amber::before {
  background: #f59e0b;
}

.card-purple::before {
  background: #8b6fc7;
}

.card-green::before {
  background: #22a06b;
}

.card-score::before {
  background: #f47b20;
}

@media screen and (max-width: 1100px) {
  .ownership-grid {
    grid-template-columns: repeat(2, minmax(180px, 1fr));
  }
}

@media screen and (max-width: 600px) {
  .ownership-header {
    display: block;
  }

  .score-summary {
    margin-top: 12px;
    text-align: left;
  }

  .ownership-grid {
    grid-template-columns: 1fr;
  }
}
